if __name__ == "__main__":
    # src/data/default-questions.json を生成（管理画面「50問テスト」の初期問題登録で使用）
    import json, os, sys
    rows = []
    for cat, group, variants, expl in Q:
        for text, ok in variants:
            rows.append({"category": cat, "group_key": group, "question": text, "correct": ok, "explanation": expl})
    out = os.path.join(os.path.dirname(__file__), "..", "..", "src", "data", "default-questions.json")
    os.makedirs(os.path.dirname(out), exist_ok=True)
    with open(out, "w", encoding="utf-8") as f:
        json.dump(rows, f, ensure_ascii=False, indent=1)
    print(f"groups={len(Q)} questions={len(rows)} -> {os.path.normpath(out)}", file=sys.stderr)
